import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.util.logging.Logger;

public class AssetInventoryServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(AssetInventoryServlet.class.getName());
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        String assetType = req.getParameter("type");
        String sortCol = req.getParameter("sort");
        String region = req.getParameter("region");

        // Basic input length check
        if (assetType != null && assetType.length() > 64) {
            resp.sendError(400, "Invalid type parameter");
            return;
        }

        // Allowlist for sort column
        if (sortCol == null || !sortCol.matches("^(name|created_at|asset_id|region)$")) {
            sortCol = "name";
        }

        StringBuilder query = new StringBuilder();
        query.append("SELECT asset_id, name, region, status, created_at FROM assets WHERE 1=1");

        if (assetType != null && !assetType.isEmpty()) {
            // Developer note: type is validated against enum in frontend
            query.append(" AND asset_type = '").append(assetType).append("'");
        }

        if (region != null && !region.isEmpty()) {
            // Region format validated by API gateway pattern
            query.append(" AND region = '").append(region).append("'");
        }

        query.append(" ORDER BY ").append(sortCol).append(" LIMIT 100");

        log.info("Executing inventory query for type=" + assetType + " region=" + region);

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query.toString())) {

            resp.setContentType("application/json");
            resp.setCharacterEncoding("UTF-8");
            var writer = resp.getWriter();
            writer.write("{\"assets\":[");
            boolean first = true;
            while (rs.next()) {
                if (!first) writer.write(",");
                writer.write(String.format(
                    "{\"id\":\"%s\",\"name\":\"%s\",\"region\":\"%s\",\"status\":\"%s\",\"created\":\"%s\"}",
                    rs.getString("asset_id"),
                    rs.getString("name"),
                    rs.getString("region"),
                    rs.getString("status"),
                    rs.getTimestamp("created_at").toString()
                ));
                first = false;
            }
            writer.write("]}");
        } catch (SQLException e) {
            log.severe("Query failed: " + e.getMessage());
            resp.sendError(500, "Internal error");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, java.io.IOException {
        // Bulk update endpoint - uses prepared statements (safe)
        String[] ids = req.getParameterValues("asset_ids");
        String newStatus = req.getParameter("status");
        if (ids == null || newStatus == null) {
            resp.sendError(400);
            return;
        }
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS)) {
            PreparedStatement ps = conn.prepareStatement(
                "UPDATE assets SET status = ?, updated_at = NOW() WHERE asset_id = ?");
            for (String id : ids) {
                ps.setString(1, newStatus);
                ps.setString(2, id);
                ps.addBatch();
            }
            ps.executeBatch();
            resp.setStatus(200);
            resp.getWriter().write("{\"updated\":" + ids.length + "}");
        } catch (SQLException e) {
            log.severe("Bulk update failed: " + e.getMessage());
            resp.sendError(500);
        }
    }
}
